changeSet.sql:
IF EXISTS (select * from sys.indexes where name = 'IX_Follow_ObjectType-ObjectID')
BEGIN
	drop INDEX [IX_Follow_ObjectType-ObjectID] ON [dbo].[Follow]
END

if exists (select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Follow' and COLUMN_NAME = 'ObjectType' and IS_NULLABLE = 'NO')
begin
	alter table [dbo].[Follow] alter column [ObjectType] [varchar](50) NULL;
end
if exists (select * from [INFORMATION_SCHEMA].[COLUMNS] where TABLE_SCHEMA = 'dbo' and TABLE_NAME = 'Follow' and COLUMN_NAME = 'ObjectID' and IS_NULLABLE = 'NO')
begin
	alter table [dbo].[Follow] alter column [ObjectID] int NULL;
end
